package net.civeira.phylax.feature.access.dcrinitialaccesstoken.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.access.dcrinitialaccesstoken.domain.DcrInitialAccessToken;
import net.civeira.phylax.feature.access.dcrinitialaccesstoken.domain.event.DcrInitialAccessTokenEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class DcrInitialAccessTokenEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<DcrInitialAccessTokenEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final DcrInitialAccessToken entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
